// MicroDuck Phase 5C permanent core gate.
//
// It checks the things that decide whether the physical workspace is honest:
//   * the pinned source revisions and the exact deployed policy bytes;
//   * the 61-value observation contract, the mouth exclusion, previous-action semantics,
//     the command block, and the control cadence;
//   * the model package: free base, fourteen policy joints, named feet, bounded actuators,
//     collision presence, valid masses;
//   * the controller, value-for-value, against an INDEPENDENTLY DERIVED reference fixture
//     generated by native/microduck_reference.py from the pinned Rust controller sources;
//   * the compatibility identity and explicit mismatch rejection;
//   * the absence of every forbidden synthetic shortcut from the physical path.
//
// Run: node tests/physics/microduck-phase5c-core.mjs
import { readFileSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { fileURLToPath } from 'node:url';
import { dirname, resolve } from 'node:path';

import {
  MICRODUCK_ACTION_WIDTH,
  MICRODUCK_COMMAND_LAYOUT,
  MICRODUCK_CONTROL_DECIMATION,
  MICRODUCK_CONTROL_HZ,
  MICRODUCK_CONTROL_INTERVAL_SECONDS,
  MICRODUCK_HEAD_JOINT_SLOTS,
  MICRODUCK_HOME_POSITION_RAD,
  MICRODUCK_MOUTH_WIRE_INDEX,
  MICRODUCK_OBSERVATION_LAYOUT,
  MICRODUCK_OBSERVATION_WIDTH,
  MICRODUCK_PHYSICS_TIMESTEP_SECONDS,
  MICRODUCK_POLICY_JOINT_ORDER,
  MICRODUCK_TUNING,
  MICRODUCK_WIRE_JOINT_ORDER,
  MicroDuckController,
  buildPolicyObservation,
  gatherPolicyValues,
  makeCommand,
  policyIdForNet,
  projectedGravityFromQuaternion,
  scatterPolicyAction,
} from '../../src/physics/microduck-controller.js';
import {
  MICRODUCK_DEPLOYED_POLICIES,
  MICRODUCK_POLICY_SHA256,
  MICRODUCK_RECONCILIATION,
  MICRODUCK_RL_SOURCE,
  MICRODUCK_RUNTIME_SOURCE,
  assertReconciliationCoverage,
  reconciliationByEvidence,
} from '../../src/physics/microduck-source-audit.js';
import {
  MICRODUCK_KICK_PACKAGE,
  MICRODUCK_LOW_TRACTION_PACKAGE,
  MICRODUCK_MODEL_PACKAGES,
  MICRODUCK_WALK_PACKAGE,
  MICRODUCK_SERVO_FORCE_NM,
} from '../../src/physics/microduck-model-package.js';
import {
  MICRODUCK_CAPABILITY_AUDIT,
  MICRODUCK_CAPABILITY_STATUS,
  MICRODUCK_LEGACY_CAPABILITY,
  MICRODUCK_PHYSICAL_CAPABILITY,
  MICRODUCK_PHYSICAL_POLICIES,
  MICRODUCK_UNSUPPORTED_CAPABILITIES,
  assertMicroDuckCompatibility,
  isPhysicallySupported,
  microduckCompatibilityIdentity,
} from '../../src/physics/microduck-capabilities.js';
import { MICRODUCK_SCENES, boundedMicroDuckCommand } from '../../src/physics/microduck-scene.js';
import { MicroDuckPhysicalEvaluator, tiltDegrees } from '../../src/physics/microduck-task-evaluator.js';
import { PARAMETER_EVIDENCE } from '../../src/physics/model-registry.js';
import { assertPhysicalScene } from '../../src/physics/backend-contract.js';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..', '..');
let passed = 0;
const failures = [];

// A rejected async check must be recorded as a failure, not escape as an unhandled rejection that
// kills the run before the summary. Pending checks are drained before the summary is printed.
const pending = [];
function check(name, fn) {
  try {
    const result = fn();
    if (result && typeof result.then === 'function') {
      pending.push(result.then(
        () => { passed += 1; console.log(`  ok  ${name}`); },
        (error) => { failures.push(name); console.log(`FAIL  ${name}\n      ${error?.message || error}`); },
      ));
      return;
    }
    passed += 1;
    console.log(`  ok  ${name}`);
  } catch (error) { failures.push(name); console.log(`FAIL  ${name}\n      ${error?.message || error}`); }
}
function assert(condition, message) { if (!condition) throw new Error(message); }
function close(actual, expected, tolerance, message) {
  const delta = Math.abs(Number(actual) - Number(expected));
  assert(Number.isFinite(delta) && delta <= tolerance, `${message} (got ${actual}, expected ${expected}, tolerance ${tolerance})`);
}
function sha256(path) { return createHash('sha256').update(readFileSync(resolve(ROOT, path))).digest('hex'); }
function readJson(path) { return JSON.parse(readFileSync(resolve(ROOT, path), 'utf8')); }

// -------------------------------------------------------------- source contract
check('pinned deployed runtime and RL revisions are full 40-character SHAs', () => {
  assert(/^[0-9a-f]{40}$/.test(MICRODUCK_RUNTIME_SOURCE.revision), 'runtime revision is not a full SHA');
  assert(/^[0-9a-f]{40}$/.test(MICRODUCK_RL_SOURCE.revision), 'RL revision is not a full SHA');
  assert(MICRODUCK_RUNTIME_SOURCE.revision === '590b986bd8c0d50ae02cb3ea2f59c463b6828168', 'the deployed pin moved');
  assert(MICRODUCK_RL_SOURCE.revision === '519142b1f5bf59fdfd44d06c205119e7fff8e3cb', 'the reconciled RL pin moved');
});

check('all nine deployed policy files carry their pinned bytes', () => {
  assert(MICRODUCK_DEPLOYED_POLICIES.length === 9, `expected nine deployed policies, found ${MICRODUCK_DEPLOYED_POLICIES.length}`);
  for (const policy of MICRODUCK_DEPLOYED_POLICIES) {
    const expected = MICRODUCK_POLICY_SHA256[policy.id];
    assert(/^[0-9a-f]{64}$/.test(expected || ''), `${policy.id} has no pinned SHA-256`);
    const actual = sha256(`assets/microduck/policies/${policy.file}`);
    assert(actual === expected, `${policy.file} is ${actual}, pinned ${expected}`);
  }
});

check('the reconciliation table covers every required parameter', () => {
  const count = assertReconciliationCoverage();
  assert(count >= 30, `reconciliation table has only ${count} rows`);
  assert(reconciliationByEvidence(PARAMETER_EVIDENCE.CALIBRATION_REQUIRED).length >= 1, 'nothing is marked calibration-required');
  const hardware = MICRODUCK_RECONCILIATION.find((row) => row.parameter === 'hardware alignment');
  assert(hardware.evidence === PARAMETER_EVIDENCE.CALIBRATION_REQUIRED, 'hardware alignment must stay calibration-required');
});

// --------------------------------------------------------- controller contract
check('the observation layout is the deployed 61-value contract', () => {
  assert(MICRODUCK_OBSERVATION_WIDTH === 61, 'observation width is not 61');
  assert(MICRODUCK_ACTION_WIDTH === 14, 'action width is not 14');
  const L = MICRODUCK_OBSERVATION_LAYOUT;
  assert(L.gyro[0] === 0 && L.gyro[1] === 3, 'gyro block moved');
  assert(L.projectedGravity[0] === 3 && L.projectedGravity[1] === 6, 'projected gravity block moved');
  assert(L.jointPositionOffset[0] === 6 && L.jointPositionOffset[1] === 20, 'joint position block moved');
  assert(L.jointVelocity[0] === 20 && L.jointVelocity[1] === 34, 'joint velocity block moved');
  assert(L.previousRawAction[0] === 34 && L.previousRawAction[1] === 48, 'previous action block moved');
  assert(L.command[0] === 48 && L.command[1] === 61, 'command block moved');
});

check('the mouth is excluded from the policy on both sides', () => {
  assert(MICRODUCK_WIRE_JOINT_ORDER.length === 15, 'wire order is not fifteen joints');
  assert(MICRODUCK_WIRE_JOINT_ORDER[MICRODUCK_MOUTH_WIRE_INDEX] === 'mouth', 'mouth is not at wire index 9');
  assert(MICRODUCK_POLICY_JOINT_ORDER.length === 14, 'policy order is not fourteen joints');
  assert(!MICRODUCK_POLICY_JOINT_ORDER.includes('mouth'), 'the mouth leaked into the policy order');
  // Distinct values so a shift is visible rather than merely nonzero.
  const action = Array.from({ length: 14 }, (_, index) => index + 1);
  const wire = scatterPolicyAction(action, 0);
  assert(wire[MICRODUCK_MOUTH_WIRE_INDEX] === 0, 'the mouth slot was written by a policy action');
  assert(wire[0] === 1 && wire[8] === 9, 'joints before the mouth are not one-to-one');
  assert(wire[10] === 10 && wire[14] === 14, 'joints after the mouth are not offset by exactly one');
  const roundTrip = gatherPolicyValues(wire);
  assert(roundTrip.every((value, index) => value === action[index]), 'gather/scatter do not round-trip');
});

check('moving the mouth cannot change any observation slot', () => {
  const base = {
    gyroRadS: [0, 0, 0], projectedGravity: [0, 0, -1],
    jointPositionRad: [...MICRODUCK_HOME_POSITION_RAD],
    jointVelocityRadS: new Array(14).fill(0),
    previousRawAction: new Array(14).fill(0),
    command: makeCommand({}),
  };
  const observation = buildPolicyObservation(base);
  for (let index = 6; index < 20; index += 1) {
    close(observation[index], 0, 1e-6, `joint slot ${index} is not zero at the home pose`);
  }
  // The physical model carries no mouth joint at all, which is the structural guarantee.
  assert(!MICRODUCK_WALK_PACKAGE.joints.some((joint) => joint.id === 'mouth'), 'the physical package declares a mouth joint');
});

check('every observation block lands at its documented offset', () => {
  const observation = buildPolicyObservation({
    gyroRadS: [1, 2, 3],
    projectedGravity: [4, 5, 6],
    jointPositionRad: MICRODUCK_HOME_POSITION_RAD.map((value, index) => (index === 0 ? value + 0.25 : value)),
    jointVelocityRadS: new Array(14).fill(0).map((_, index) => (index === 3 ? 0.5 : 0)),
    previousRawAction: new Array(14).fill(0).map((_, index) => (index === 0 ? -0.5 : index === 13 ? 0.75 : 0)),
    command: makeCommand({ twist: [0.1, 0.2, 0.3], head: [0.4, 0.5, 0.6, 0.7], body: { z: 0.8, roll: 0.9, pitch: 1.0 } }),
  });
  close(observation[0], 1, 1e-6, 'gyro x'); close(observation[2], 3, 1e-6, 'gyro z');
  close(observation[3], 4, 1e-6, 'gravity x'); close(observation[5], 6, 1e-6, 'gravity z');
  close(observation[6], 0.25, 1e-6, 'joint position offset');
  close(observation[23], 0.5, 1e-6, 'joint velocity');
  close(observation[34], -0.5, 1e-6, 'previous action first');
  close(observation[47], 0.75, 1e-6, 'previous action last');
  close(observation[48], 0.1, 1e-6, 'twist vx'); close(observation[50], 0.3, 1e-6, 'twist vyaw');
  close(observation[51], 0.4, 1e-6, 'neck pitch'); close(observation[54], 0.7, 1e-6, 'head roll');
});

check('body x, y and yaw are always zero, and the body block is z, roll, pitch', () => {
  const observation = buildPolicyObservation({
    gyroRadS: [0, 0, 0], projectedGravity: [0, 0, -1],
    jointPositionRad: [...MICRODUCK_HOME_POSITION_RAD], jointVelocityRadS: new Array(14).fill(0),
    previousRawAction: new Array(14).fill(0),
    command: makeCommand({ body: { z: 0.8, roll: 0.9, pitch: 1.0 } }),
  });
  assert(observation[MICRODUCK_COMMAND_LAYOUT.bodyXY[0]] === 0, 'body x is not zero');
  assert(observation[MICRODUCK_COMMAND_LAYOUT.bodyXY[0] + 1] === 0, 'body y is not zero');
  assert(observation[MICRODUCK_COMMAND_LAYOUT.bodyYaw] === 0, 'body yaw is not zero');
  close(observation[MICRODUCK_COMMAND_LAYOUT.bodyZ], 0.8, 1e-6, 'body z');
  close(observation[MICRODUCK_COMMAND_LAYOUT.bodyRoll], 0.9, 1e-6, 'body roll');
  close(observation[MICRODUCK_COMMAND_LAYOUT.bodyPitch], 1.0, 1e-6, 'body pitch');
});

check('the controller feeds back the RAW policy action, not the scaled target', () => {
  const controller = new MicroDuckController({ availablePolicies: MICRODUCK_PHYSICAL_POLICIES });
  const raw = Array.from({ length: 14 }, (_, index) => 0.1 * (index + 1));
  const observation = {
    gyroRadS: [0, 0, 0], projectedGravity: [0, 0, -1],
    jointPositionRad: [...MICRODUCK_HOME_POSITION_RAD], jointVelocityRadS: new Array(14).fill(0),
  };
  controller.step({ observation, command: makeCommand({ twist: [0.3, 0, 0] }), infer: () => raw });
  assert(controller.previousRawAction.every((value, index) => Math.abs(value - raw[index]) < 1e-12),
    'the controller stored something other than the raw action');
  // The second tick must present the raw action, and it must differ from the scaled target.
  let seen = null;
  controller.step({ observation, command: makeCommand({ twist: [0.3, 0, 0] }), infer: (_, obs) => { seen = Array.from(obs.slice(34, 48)); return raw; } });
  assert(seen.every((value, index) => Math.abs(value - raw[index]) < 1e-6), 'the observation fed back a processed action');
  const scaled = raw[0] * MICRODUCK_TUNING.actionScale;
  assert(Math.abs(seen[0] - scaled) > 1e-6, 'the raw action and the scaled action are indistinguishable in this fixture');
});

check('the control cadence is the deployed 50 Hz over a 5 ms physics step', () => {
  close(MICRODUCK_PHYSICS_TIMESTEP_SECONDS, 0.005, 1e-12, 'physics timestep');
  assert(MICRODUCK_CONTROL_DECIMATION === 4, 'control decimation is not 4');
  close(MICRODUCK_CONTROL_INTERVAL_SECONDS, 0.02, 1e-12, 'control interval');
  close(MICRODUCK_CONTROL_HZ, 50, 1e-9, 'control rate');
  close(MICRODUCK_WALK_PACKAGE.physics.timestepSeconds, MICRODUCK_PHYSICS_TIMESTEP_SECONDS, 1e-12, 'package timestep');
  assert(MICRODUCK_WALK_PACKAGE.controlDecimation === MICRODUCK_CONTROL_DECIMATION, 'package decimation disagrees with the controller');
});

check('skill selection follows the deployed priority chain', () => {
  const controller = new MicroDuckController({ availablePolicies: MICRODUCK_PHYSICAL_POLICIES });
  const walking = makeCommand({ twist: [0.3, 0, 0] });
  assert(controller.selectNet(walking).net === 'walk', 'a moving command did not select walk');
  assert(controller.selectNet(makeCommand({})).net === 'stand', 'a still command did not select stand');
  controller.requestSkill('ground_pick');
  assert(controller.selectNet(walking).net === 'ground_pick', 'ground pick did not take priority over walking');
  controller.requestSkill('kick_right');
  assert(controller.selectNet(walking).net === 'kick_right', 'a kick did not take priority over ground pick');
  controller.requestSkill('roulade');
  assert(controller.selectNet(walking).net === 'roulade', 'a roulade did not take top priority');
  // A kick presents an all-zero command, so it runs at standing tuning like the prototype.
  const kickOnly = new MicroDuckController({ availablePolicies: MICRODUCK_PHYSICAL_POLICIES });
  kickOnly.requestSkill('kick_left');
  const { net, effective } = kickOnly.selectNet(walking);
  assert(effective.twist.every((value) => value === 0), 'a kick did not zero the command');
  assert(kickOnly.tuningFor(net, effective).scale === MICRODUCK_TUNING.standingActionScale, 'a kick did not run at standing scale');
});

check('a reset clears the previous action and the filter anchor', () => {
  const controller = new MicroDuckController({ availablePolicies: MICRODUCK_PHYSICAL_POLICIES });
  const observation = {
    gyroRadS: [0, 0, 0], projectedGravity: [0, 0, -1],
    jointPositionRad: [...MICRODUCK_HOME_POSITION_RAD], jointVelocityRadS: new Array(14).fill(0),
  };
  controller.step({ observation, command: makeCommand({ twist: [0.3, 0, 0] }), infer: () => new Array(14).fill(0.4) });
  controller.requestSkill('kick_left');
  assert(controller.previousTargets !== null, 'the filter anchor was never set');
  controller.reset();
  assert(controller.previousRawAction.every((value) => value === 0), 'reset left a stale previous action');
  assert(controller.previousTargets === null, 'reset left a stale filter anchor');
  assert(controller.kick === null && controller.sit === 'up', 'reset left a skill window open');
});

check('projected gravity matches the upstream quaternion helper', () => {
  // Cross-checked value-for-value against native/microduck_reference.py's
  // quat_rotate_inverse, which is the upstream infer_policy.py helper.
  const cases = [
    [[1, 0, 0, 0], [0, 0, -1], 'upright'],
    [[Math.SQRT1_2, 0, -Math.SQRT1_2, 0], [-1, 0, 0], 'face down'],
    [[Math.SQRT1_2, 0, Math.SQRT1_2, 0], [1, 0, 0], 'face up'],
    [[Math.SQRT1_2, Math.SQRT1_2, 0, 0], [0, -1, 0], 'on its side'],
  ];
  for (const [quaternion, expected, label] of cases) {
    const actual = projectedGravityFromQuaternion(quaternion);
    for (let axis = 0; axis < 3; axis += 1) close(actual[axis], expected[axis], 1e-9, `${label} gravity axis ${axis}`);
    close(Math.hypot(...actual), 1, 1e-9, `${label}: projected gravity must stay a unit vector`);
  }
});

// ------------------------------------------------------ independent conformance
check('the controller matches the independently derived reference fixture', () => {
  const fixture = readJson('assets/microduck/fixtures/controller-conformance.json');
  assert(fixture.schema === 'robobuddy.microduck-controller-conformance.v1', 'unexpected fixture schema');
  assert(fixture.pins.microduck === MICRODUCK_RUNTIME_SOURCE.revision, 'the fixture was generated against a different runtime pin');
  assert(fixture.pins.microduck_rl === MICRODUCK_RL_SOURCE.revision, 'the fixture was generated against a different RL pin');
  assert(fixture.model.sha256 === MICRODUCK_WALK_PACKAGE.sha256, 'the fixture was generated against a different model');
  assert(fixture.policy.sha256 === MICRODUCK_POLICY_SHA256.walking, 'the fixture was generated against different policy bytes');
  assert(fixture.contract.observationWidth === MICRODUCK_OBSERVATION_WIDTH, 'fixture observation width');
  assert(fixture.contract.actionScale === MICRODUCK_TUNING.actionScale, 'fixture action scale');
  assert(fixture.contract.headLowpassAlpha === MICRODUCK_TUNING.headLowpassAlpha, 'fixture head filter');
  assert(fixture.contract.legsLowpassAlpha === MICRODUCK_TUNING.legsLowpassAlpha, 'fixture legs filter');
  assert(fixture.contract.headJointSlots.every((slot, index) => slot === MICRODUCK_HEAD_JOINT_SLOTS[index]), 'fixture head slots');
  assert(fixture.contract.policyJointOrder.every((id, index) => id === MICRODUCK_POLICY_JOINT_ORDER[index]), 'fixture joint order');
  assert(fixture.samples.length >= 4, 'the fixture carries too few sampled states');

  for (const sample of fixture.samples) {
    // Observation assembly: rebuild the sample's 61-value input from its physical inputs.
    const rebuilt = buildPolicyObservation({
      gyroRadS: sample.input.gyroRadS,
      projectedGravity: sample.input.projectedGravity,
      jointPositionRad: sample.input.jointPositionRad,
      jointVelocityRadS: sample.input.jointVelocityRadS,
      previousRawAction: sample.input.previousRawAction,
      command: makeCommand({
        twist: sample.input.command.twist,
        head: sample.input.command.head,
        body: sample.input.command.body,
      }),
    });
    assert(rebuilt.length === sample.observation.length, `tick ${sample.tick}: observation width`);
    for (let index = 0; index < rebuilt.length; index += 1) {
      close(rebuilt[index], sample.observation[index], 1e-6, `tick ${sample.tick}: observation slot ${index}`);
    }
    // Post-processing: home pose + scale x scattered action, then the deployed filters.
    const controller = new MicroDuckController({ availablePolicies: MICRODUCK_PHYSICAL_POLICIES });
    controller.previousTargets = sample.input.previousTargetsRad;
    const targets = controller.targetsFor(sample.rawAction, sample.actionScale);
    for (let slot = 0; slot < targets.length; slot += 1) {
      close(targets[slot], sample.targetsRad[slot], 1e-6, `tick ${sample.tick}: target ${MICRODUCK_POLICY_JOINT_ORDER[slot]}`);
    }
    assert(sample.wireTargets.mouthWireIndex === MICRODUCK_MOUTH_WIRE_INDEX, 'fixture mouth index');
    assert(sample.wireTargets.mouthIsPolicyControlled === false, 'fixture claims the mouth is policy-controlled');
  }
});

check('an off-by-one mouth mapping is caught by the fixture', () => {
  const fixture = readJson('assets/microduck/fixtures/controller-conformance.json');
  const sample = fixture.samples[fixture.samples.length - 1];
  // Deliberately corrupt the mapping the way an off-by-one would: shift the action by one
  // slot. The fixture must reject it.
  const shifted = [sample.rawAction[sample.rawAction.length - 1], ...sample.rawAction.slice(0, -1)];
  const controller = new MicroDuckController({ availablePolicies: MICRODUCK_PHYSICAL_POLICIES });
  controller.previousTargets = sample.input.previousTargetsRad;
  const targets = controller.targetsFor(shifted, sample.actionScale);
  const differs = targets.some((value, slot) => Math.abs(value - sample.targetsRad[slot]) > 1e-6);
  assert(differs, 'a one-slot action shift produced identical targets, so the fixture cannot catch it');
});

// ------------------------------------------------------------- model contract
check('every MicroDuck model package declares a free base and fourteen policy joints', () => {
  assert(MICRODUCK_MODEL_PACKAGES.length === 4, `expected four task-specific packages, found ${MICRODUCK_MODEL_PACKAGES.length}`);
  for (const modelPackage of MICRODUCK_MODEL_PACKAGES) {
    const trunk = modelPackage.bodies.find((body) => body.id === 'trunk_base');
    assert(trunk?.freeJointId === 'trunk_base_freejoint', `${modelPackage.id} has no free trunk`);
    assert(modelPackage.joints.length === 14, `${modelPackage.id} declares ${modelPackage.joints.length} joints`);
    assert(modelPackage.actuators.length === 14, `${modelPackage.id} declares ${modelPackage.actuators.length} actuators`);
    for (const [index, joint] of modelPackage.joints.entries()) {
      assert(joint.id === MICRODUCK_POLICY_JOINT_ORDER[index], `${modelPackage.id} joint ${index} is ${joint.id}`);
      assert(Array.isArray(joint.rangeRad) && joint.rangeRad[0] < joint.rangeRad[1], `${joint.id} has no valid range`);
    }
    for (const actuator of modelPackage.actuators) {
      assert(actuator.command === 'position-rad', `${actuator.id} is not a position actuator`);
      assert(Math.abs(actuator.sourceForceRangeNm[1] - MICRODUCK_SERVO_FORCE_NM) < 1e-12, `${actuator.id} lost the source XML fallback envelope`);
      assert(actuator.forceRangeNm[1] > MICRODUCK_SERVO_FORCE_NM, `${actuator.id} was not converted to the BAM voltage-domain torque ceiling`);
      assert(/BAM XL330 M6/.test(actuator.actuatorModel), `${actuator.id} does not declare the BAM plant`);
      assert(actuator.forceRangeNm.every(Number.isFinite), `${actuator.id} has an unbounded force range`);
      assert(actuator.controlRangeRad.every(Number.isFinite), `${actuator.id} has an unbounded control range`);
    }
    assert(modelPackage.initialJointPositionsRad, `${modelPackage.id} declares no initial state`);
    for (const [slot, id] of MICRODUCK_POLICY_JOINT_ORDER.entries()) {
      close(modelPackage.initialJointPositionsRad[id], MICRODUCK_HOME_POSITION_RAD[slot], 1e-12, `${modelPackage.id} home pose for ${id}`);
    }
  }
});

check('the committed model assets carry their registered hashes and the named contacts', () => {
  for (const modelPackage of MICRODUCK_MODEL_PACKAGES) {
    const actual = sha256(modelPackage.asset);
    assert(actual === modelPackage.sha256, `${modelPackage.asset} is ${actual}, registered ${modelPackage.sha256}`);
    const xml = readFileSync(resolve(ROOT, modelPackage.asset), 'utf8');
    assert(xml.includes('name="left_foot_collision"'), `${modelPackage.asset} has no named left foot collider`);
    assert(xml.includes('name="right_foot_collision"'), `${modelPackage.asset} has no named right foot collider`);
    assert(xml.includes('name="microduck_floor"'), `${modelPackage.asset} has no named floor`);
    assert(xml.includes('name="trunk_base_freejoint"'), `${modelPackage.asset} has no free trunk joint`);
    assert(xml.includes('name="imu_ang_vel"'), `${modelPackage.asset} has no source-named imu gyro`);
    assert(!/<equality>/.test(xml), `${modelPackage.asset} declares an active equality block`);
    assert(!/\bweld\b/.test(xml), `${modelPackage.asset} declares a weld`);
    assert(/type="mesh"/.test(xml), `${modelPackage.asset} no longer uses source mesh geometry`);
    assert(/mesh="sole_left"/.test(xml) && /mesh="sole_right"/.test(xml), `${modelPackage.asset} lost exact source sole meshes`);
    assert(/mass="0.264385"/.test(xml), `${modelPackage.asset} lost the source trunk inertial`);
  }
  const walk = readFileSync(resolve(ROOT, MICRODUCK_WALK_PACKAGE.asset), 'utf8');
  // Pinned robot_walk: soles collide with the world; leg and power_support are self-collision-only.
  assert(/name="left_foot_collision"[^>]*mesh="sole_left"/.test(walk), 'walk plant lost the source left-sole collision');
  assert(/name="right_foot_collision"[^>]*mesh="sole_right"/.test(walk), 'walk plant lost the source right-sole collision');
  assert(/class="self_collision_only"[^>]*mesh="leg"/.test(walk), 'walk plant lost source leg self-collision');
  assert(/class="self_collision_only"[^>]*mesh="power_support"/.test(walk), 'walk plant lost source power-support self-collision');
  const lowTraction = readFileSync(resolve(ROOT, MICRODUCK_LOW_TRACTION_PACKAGE.asset), 'utf8');
  assert(lowTraction.includes('friction="0.02 0.005 0.0001"'), 'the reduced-traction fixture does not declare its degraded friction');
  const kick = readFileSync(resolve(ROOT, MICRODUCK_KICK_PACKAGE.asset), 'utf8');
  assert(kick.includes('name="microduck_ball_geom"') && kick.includes('mass="0.015"'), 'the kick package lost the source ball');
  assert((kick.match(/class="collision"/g) || []).length > (walk.match(/class="collision"/g) || []).length,
    'kick/recovery plant is not using the broader source all-collision geometry');
  const notice = readFileSync(resolve(ROOT, 'THIRD_PARTY_NOTICES.md'), 'utf8');
  assert(notice.includes('Creative Commons BY-SA-NC') && notice.includes('version'), 'collision asset license/version scope is not disclosed');
});

