// --------------------------------------------------------------- evaluation
check('the evaluator reads locomotion from contact, not from a distance alone', () => {
  const evaluator = new MicroDuckPhysicalEvaluator({ commandedTwist: [0.3, 0, 0] });
  // A robot that translates without ever lifting a foot is not walking.
  for (let index = 0; index < 20; index += 1) {
    evaluator.observe({
      simulationTimeSeconds: index * 0.02,
      bodies: { trunk_base: { positionM: [index * 0.05, 0, 0.116], quaternionWxyz: [1, 0, 0, 0] } },
      footContacts: { floor: { left_foot_collision: true, right_foot_collision: true }, ball: [] },
    });
  }
  const slid = evaluator.locomotionVerdict();
  assert(!slid.walked, 'sliding without any contact transition was counted as walking');
  assert(slid.reasons.some((reason) => /contact transitions/.test(reason)), 'the verdict does not name the missing contact transitions');

  const walker = new MicroDuckPhysicalEvaluator({ commandedTwist: [0.3, 0, 0] });
  for (let index = 0; index < 40; index += 1) {
    const left = index % 8 < 4;
    walker.observe({
      simulationTimeSeconds: index * 0.02,
      bodies: { trunk_base: { positionM: [index * 0.02, 0, 0.116], quaternionWxyz: [1, 0, 0, 0] } },
      footContacts: { floor: { left_foot_collision: left, right_foot_collision: !left }, ball: [] },
    });
  }
  const walked = walker.locomotionVerdict();
  assert(walked.walked, `alternating contact with displacement was not counted as walking: ${walked.reasons?.join('; ')}`);
  assert(walked.report.commandedAxisDistanceM > 0.05, 'the commanded-axis distance was not measured');
});

check('ball motion without a named foot contact is never reported as a kick', () => {
  const evaluator = new MicroDuckPhysicalEvaluator({ commandedTwist: [0, 0, 0] });
  for (let index = 0; index < 5; index += 1) {
    evaluator.observe({
      simulationTimeSeconds: index * 0.02,
      bodies: {
        trunk_base: { positionM: [0, 0, 0.116], quaternionWxyz: [1, 0, 0, 0] },
        microduck_ball: { positionM: [0.09 + index * 0.1, -0.042, 0.035], quaternionWxyz: [1, 0, 0, 0] },
      },
      footContacts: { floor: { left_foot_collision: true, right_foot_collision: true }, ball: [] },
    });
  }
  const report = evaluator.report();
  assert(report.ball.planarDistanceM > 0.3, 'the ball did not move in this fixture');
  assert(report.ball.movedByFootContact === false, 'ball motion without contact was attributed to a kick');
  assert(report.ball.unattributedMotion === true, 'unattributed ball motion was not flagged');
});

