// ------------------------------------------------- forbidden physical shortcuts
check('the physical path contains no synthetic root, ball, boundary or recovery shortcut', () => {
  const physicalModules = [
    'src/physics/microduck-controller.js',
    'src/physics/microduck-mujoco-worker.js',
    'src/physics/microduck-physical-simulator.js',
    'src/physics/microduck-task-evaluator.js',
    'src/physics/microduck-scene.js',
    'src/physics/microduck-capabilities.js',
    'src/physics/microduck-model-package.js',
    'src/webmcp/microduck-physical-control.js',
    'src/runtime/microduck-physical-bridge.js',
  ];
  // Legacy synthetic behaviour lives in these modules and must not be reachable from the
  // physical path at all.
  const forbiddenImports = [
    'microduck/ball-motion.js', 'microduck/field-bounds.js', 'microduck/mujoco-dynamics.js',
    'microduck/policy-simulator.js',
  ];
  const forbiddenCalls = [
    'applyConfiguredKick', 'applyRollingResistance', 'stopPlanarBodyAtFieldEdge', 'setUpright',
    'BALL_KICK_IMPULSE_NS', 'MICRODUCK_FIELD_HALF_EXTENT_M',
  ];
  for (const path of physicalModules) {
    const source = readFileSync(resolve(ROOT, path), 'utf8');
    for (const needle of forbiddenImports) {
      assert(!source.includes(needle), `${path} imports the legacy synthetic module ${needle}`);
    }
    for (const needle of forbiddenCalls) {
      assert(!source.includes(needle), `${path} references the legacy synthetic symbol ${needle}`);
    }
    // qvel/qpos may only be written inside the worker's declared setup path.
    if (!path.endsWith('microduck-mujoco-worker.js')) {
      assert(!/\bqvel\b/.test(source), `${path} touches qvel outside the authority`);
      assert(!/\bqpos\b/.test(source), `${path} touches qpos outside the authority`);
    }
  }
  // Inside the worker, every qpos/qvel write must sit in the setup function.
  const worker = readFileSync(resolve(ROOT, 'src/physics/microduck-mujoco-worker.js'), 'utf8');
  const setupStart = worker.indexOf('function setup(');
  const setupEnd = worker.indexOf('self.onmessage');
  assert(setupStart > 0 && setupEnd > setupStart, 'the worker setup function could not be located');
  const initialStart = worker.indexOf('function applyDeclaredInitialState(');
  const initialEnd = worker.indexOf('function disposeModel(');
  const writes = [...worker.matchAll(/data\.(qpos|qvel)\[[^\]]*\]\s*=/g)];
  assert(writes.length > 0, 'no state writes were found at all, so this check proves nothing');
  for (const match of writes) {
    const index = match.index;
    const inSetup = index >= setupStart && index <= setupEnd;
    const inInitial = index >= initialStart && index <= initialEnd;
    assert(inSetup || inInitial, `worker writes ${match[0]} outside the declared setup/reset path (offset ${index})`);
  }
  // Ordinary control writes the dedicated position-target buffer only. BAM is the sole
  // writer of MuJoCo ctrl, where ctrl is motor torque after runtime conversion.
  const commandStart = worker.indexOf('function command(');
  const commandEnd = worker.indexOf('function setup(');
  const commandBody = worker.slice(commandStart, commandEnd);
  assert(/requestedTargets\[actuator\.id\] = target/.test(commandBody), 'the command path does not preserve actuator target intent');
  assert(!/data\.ctrl/.test(commandBody), 'the high-level command path bypasses BAM and writes MuJoCo torque directly');
  assert(!/qpos|qvel/.test(commandBody), 'the command path touches physical state directly');
  assert(/data\.ctrl\[index\] = clamp\(motorTorque/.test(worker), 'BAM is no longer the sole MuJoCo torque writer');
});

check('the live-Python surface exposes commands and skills, never joint or state writes', () => {
  const source = readFileSync(resolve(ROOT, 'src/runtime/microduck-physical-bridge.js'), 'utf8');
  // The learner-facing command surface is the robot's own bounded command, not joint targets.
  assert(/COMMAND_FIELDS = Object\.freeze\(\['vx', 'vy', 'vyaw'/.test(source), 'the Python command surface changed shape');
  assert(!source.includes('set_joint_targets'), 'the Python bridge can write joint targets directly');
  assert(!source.includes('applySetup'), 'the Python bridge can reach the declared setup path');
  assert(!/set_trunk_orientation|set_object_pose|set_actuation_enabled/.test(source), 'the Python bridge can write physical state');
  // A reset is never a recovery and never a success.
  assert(/countsAsRecovery: false/.test(source), 'the Python reset does not disclaim being a recovery');
  // The three views stay separate, so a program cannot mistake a request for a measurement.
  assert(/requested: state\.requested/.test(source) && /controller: state\.controller/.test(source) && /actual: state\.actual/.test(source),
    'the Python observation stopped separating request, controller decision and actual state');
});

